def solve(grid):
    """Solve according to expansion rule: each 3 expands in 4 directions until blocked by 2 or edge"""
    h, w = len(grid), len(grid[0])

    # Find all '3' positions
    threes = []
    twos = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                threes.append((r, c))
            elif grid[r][c] == 2:
                twos.add((r, c))

    result = [row[:] for row in grid]  # copy

    for sr, sc in threes:
        # Expand up
        r = sr - 1
        while r >= 0:
            if (r, sc) in twos:
                break
            if result[r][sc] != 0:
                break
            result[r][sc] = 3
            r -= 1

        # Expand down
        r = sr + 1
        while r < h:
            if (r, sc) in twos:
                break
            if result[r][sc] != 0:
                break
            result[r][sc] = 3
            r += 1

        # Expand left
        c = sc - 1
        while c >= 0:
            if (sr, c) in twos:
                break
            if result[sr][c] != 0:
                break
            result[sr][c] = 3
            c -= 1

        # Expand right
        c = sc + 1
        while c < w:
            if (sr, c) in twos:
                break
            if result[sr][c] != 0:
                break
            result[sr][c] = 3
            c += 1

    return result

