def solve_v4(grid):
    """Handle both cases: with single 3 and without 3"""
    h, w = len(grid), len(grid[0])

    # Find all non-zero positions
    twos = set()
    threes = []
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val == 2:
                twos.add((r,c))
            elif val == 3:
                threes.append((r,c))

    result = [row[:] for row in grid]

    if not threes:
        # Case 1: No 3s in input - connect aligned 2s horizontally/vertically
        # For each row with >=2 twos, fill between outermost 2s with 3s
        for r in range(h):
            cols_with_2 = [c for c in range(w) if (r,c) in twos]
            if len(cols_with_2) >= 2:
                min_c, max_c = min(cols_with_2), max(cols_with_2)
                for c in range(min_c, max_c + 1):
                    if (r, c) not in twos:
                        result[r][c] = 3

        # Do same for columns
        for c in range(w):
            rows_with_2 = [r for r in range(h) if (r,c) in twos]
            if len(rows_with_2) >= 2:
                min_r, max_r = min(rows_with_2), max(rows_with_2)
                for r in range(min_r, max_r + 1):
                    if (r, c) not in twos:
                        result[r][c] = 3

    else:
        # Case 2: Has exactly one 3 - expand diagonally from it
        sr, sc = threes[0]

        # Expand in 8 directions along lines where |dr| = |dc|
        dirs = [(-1,-1), (-1,1), (1,-1), (1,1)]
        for dr, dc in dirs:
            r, c = sr + dr, sc + dc
            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] != 0:  # blocked by non-zero
                    break
                result[r][c] = 3
                r += dr
                c += dc

    return result

