def solve_diagonals_only(grid):
    """Fill all diagonals passing through any non-zero cell"""
    h, w = len(grid), len(grid[0])

    result = [row[:] for row in grid]

    # For each non-zero cell, mark all cells on its diagonals
    for sr in range(h):
        for sc in range(w):
            val = grid[sr][sc]
            if val == 0:
                continue

            # Main diagonals through (sr, sc): r-c = sr-sc
            diag_id = sr - sc
            seen_main = set()
            for r in range(h):
                for c in range(w):
                    if r - c == diag_id:
                        if grid[r][c] != 0:
                            seen_main.add((r,c))

            # Anti-diagonals: r+c = sr+sc
            anti_id = sr + sc
            seen_anti = set()
            for r in range(h):
                for c in range(w):
                    if r + c == anti_id:
                        if grid[r][c] != 0:
                            seen_anti.add((r,c))

    return result

