def solve_iterative_expansion(grid):
    """Iteratively expand from each source 3"""
    h, w = len(grid), len(grid[0])

    # Start with original sources
    current_3s = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                current_3s.add((r,c))

    result = [row[:] for row in grid]

    # Iteratively expand in ALL directions (8-way including diagonals)
    max_steps = 6  # Grid is 11x11

    for step in range(max_steps):
        new_3s = set(current_3s)

        for sr, sc in current_3s:
            # Check all 8 neighbors
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = sr + dr, sc + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] == 0 and (nr, nc) not in current_3s:
                            new_3s.add((nr, nc))

        current_3s = new_3s
        if not current_3s:
            break

        for r, c in current_3s:
            if grid[r][c] == 0:
                result[r][c] = 3

    return result

